steps.snippet:
storage = binding.get("storage_area") or binding.get("storage") or binding.get("volume")
idx = None
if storage:
    idx = device.find(text=storage, contains=True)
if idx is None:
    idx = device.find(text="sdk_gphone", contains=True)  # emulator volume label prefix
if idx is None:
    raise LookupError(f"Storage root entry for '{storage}' not found on picker screen")
device.click(idx)
device.settle(1)

target = binding["destination_folder"]
for _ in range(10):
    if device.find(text=target) is not None or device.find(contains=target) is not None:
        break
    device.scroll("down")
    device.settle(1)
if device.find(text=target) is None and device.find(contains=target) is None:
    raise LookupError(f"Folder '{target}' not found in picker after scrolling")

storage = binding.get('storage_area') or binding.get('storage') or binding.get('volume_name')
if not storage:
    raise KeyError("binding does not contain the storage area name")
idx = device.find(text=storage, contains=True)
if idx is None:
    roots_btn = device.find(description='Show roots', clickable=True)
    if roots_btn is not None:
        device.click(roots_btn)
        device.settle(1)
    idx = device.find(text=storage, contains=True)
if idx is None:
    raise LookupError(f"Storage root '{storage}' not found on screen (drawer open or closed)")
device.click(idx)

idx = device.find(text='Move to…')
if idx is None:
    idx = device.find(contains='Move to')
if idx is None:
    raise RuntimeError("Menu item 'Move to…' not found; overflow menu may not be open")
device.click(idx)

idx = device.find(description="Show roots", clickable=True)
if idx is None:
    # drawer may already be open
    if device.find(text="sdk_gphone64_arm64", contains=True) is None:
        raise RuntimeError("Roots toggle ('Show roots') not found and root drawer not visible")
else:
    device.click(idx)
device.settle(1)

storage = binding.get('storage_area') or binding.get('storage')
if not storage:
    raise ValueError("binding does not provide the storage area name")
idx = device.find(text=storage)
if idx is None:
    idx = device.find(contains=storage)
if idx is None:
    raise LookupError(f"storage root '{storage}' not found on screen")
device.click(idx)

target = binding["destination_folder"]
for _ in range(10):
    if device.find(text=target) is not None:
        break
    device.scroll("down")
    device.settle(1)
else:
    raise LookupError(f"Destination folder '{target}' not visible after scrolling")
